<template>
  <p class="view-bridge">{{ cleanText }}</p>
</template>

<script>
export default {
  name: 'ViewBridge',
  props: {
    bridge: {
      type: Object,
      required: true,
    },
  },
  computed: {
    cleanText() {
      return String(this.bridge?.text || '')
        .replace(/\s*\[[a-z0-9_-]+:[^\]]+\]/gi, '')
        .replace(/\s*\[(?:\d+(?:\s*,\s*\d+)*)\]/g, '')
        .replace(/\s+([.,!?])/g, '$1')
        .trim();
    },
  },
};
</script>

<style scoped>
.view-bridge {
  max-width: 46em;
  margin: 1.6rem 0;
  color: #4f4f4f;
  font-size: inherit;
  line-height: inherit;
  text-wrap: pretty;
}

body.dark-mode .view-bridge {
  color: #c2c2c2;
}
</style>
