import { retrieveAskContexts, sourceDisplayTitle } from './askRetrieval.js';
import { viewRichBlocks } from '../data/viewRichBlocks.js';

let viewItemsPromise = null;

async function viewItems() {
  if (!viewItemsPromise) {
    viewItemsPromise = fetch('/assets/view-index.json', { cache: 'no-cache' })
      .then((res) => {
        if (!res.ok) throw new Error(`view-index.json ${res.status}`);
        return res.json();
      });
  }
  return viewItemsPromise;
}

function richSources() {
  return (viewRichBlocks || []).map((block) => ({
    source_id: block.id,
    route: block.route,
    page: block.title,
    title: block.title,
    anchor: block.anchor || '',
    body: block.description,
    parts: [block.description, (block.topics || []).join(', ')].filter(Boolean),
    component_description: block.componentDescription || block.description,
    narrative_guidance: block.narrativeGuidance || '',
    view_kind: block.kind === 'interactive' ? 'interactive' : 'embed',
    presentations: [block.allowedPresentation],
    media: block.media || [],
    entity: block.entity || null,
    topics: block.topics || [],
    activation_topics: block.activationTopics || block.topics || [],
    rich: true,
  }));
}

const RICH_STOP_WORDS = new Set([
  'a', 'about', 'an', 'and', 'are', 'at', 'be', 'did', 'do', 'does', 'for',
  'find', 'from', 'get', 'go', 'has', 'have', 'henry', 'how', 'i', 'in', 'is', 'it',
  'know', 'like', 'live', 'love', 'me', 'more', 'of', 'on', 'see', 'tell',
  'that', 'the', 'think', 'this', 'to', 'use', 'want', 'was', 'went', 'what',
  'where', 'which', 'who', 'why', 'with', 'you',
]);

const ARCHIVE_PERIOD_PATTERN = /\b(?:early|earlier|teen(?:age|ager)?|secondary school|high school|junior high|school years|growing up)\b/i;
const BROAD_PROJECT_PATTERN = /\b(?:project|projects|builds|built|made|created)\b/i;
const ARCHIVE_GENERIC_TOKENS = new Set([
  'build', 'built', 'building', 'code', 'coding', 'computer', 'computing', 'project',
  'projects', 'program', 'programming', 'software', 'technical', 'technology', 'tool', 'tools',
]);

function relevanceTokens(value) {
  return String(value || '').toLowerCase().match(/[a-z0-9]+/g)?.filter((token) => (
    token.length > 1 && !RICH_STOP_WORDS.has(token)
  )) || [];
}

// Whole-word matching only, so a query token like "view" never matches inside
// another word such as "Kiwiview". Tokens come from [a-z0-9]+ so they are safe
// to embed in a regular expression.
function hasWord(text, token) {
  return new RegExp(`\\b${token}\\b`).test(String(text || '').toLowerCase());
}

function sourceSearchText(source, activationOnly = false) {
  if (activationOnly && Array.isArray(source?.activation_topics)) {
    return source.activation_topics.join(' ').toLowerCase();
  }
  return [
    source?.source_id,
    source?.page,
    source?.title,
    source?.body,
    source?.component_description,
    source?.narrative_guidance,
    ...(source?.parts || []),
    ...(source?.topics || []),
    ...Object.values(source?.entity || {}),
  ].join(' ').toLowerCase();
}

function directlyMatches(source, tokens) {
  if (!tokens.length) return false;
  const text = sourceSearchText(source, !!source?.rich);
  return tokens.some((token) => hasWord(text, token));
}

function isFormativeArchive(source) {
  return source?.route === '/early';
}

export function prioritizeFormativeArchive(sources, message) {
  const periodMatch = ARCHIVE_PERIOD_PATTERN.test(String(message || ''));
  const broadProjectMatch = BROAD_PROJECT_PATTERN.test(String(message || ''));
  const specificTokens = relevanceTokens(message).filter((token) => !ARCHIVE_GENERIC_TOKENS.has(token));
  return (sources || [])
    .map((source, index) => {
      if (!isFormativeArchive(source)) return { source, index, tier: 1 };
      const exactDomainMatch = specificTokens.some((token) => hasWord(sourceSearchText(source), token));
      const direct = periodMatch || exactDomainMatch;
      const signatureForBroadStory = broadProjectMatch && source.entity?.signature === true;
      return {
        source: (direct || signatureForBroadStory) && source.presentations?.includes('component')
          ? { ...source, direct_component_match: true, required_component_match: true }
          : source,
        index,
        tier: direct ? 0 : signatureForBroadStory ? 2 : 3,
      };
    })
    .sort((a, b) => a.tier - b.tier || a.index - b.index)
    .map((entry) => entry.source);
}

export function formativeArchiveCandidates(allSources, message) {
  const text = String(message || '');
  const archive = (allSources || []).filter(isFormativeArchive);
  if (ARCHIVE_PERIOD_PATTERN.test(text)) return archive;
  const specificTokens = relevanceTokens(text).filter((token) => !ARCHIVE_GENERIC_TOKENS.has(token));
  if (specificTokens.length) {
    const domainMatches = archive.filter((source) => specificTokens.some((token) => hasWord(sourceSearchText(source), token)));
    if (domainMatches.length) return domainMatches;
  }
  if (BROAD_PROJECT_PATTERN.test(text)) {
    return archive.filter((source) => source.entity?.signature === true);
  }
  return [];
}

export function broadProjectCandidates(allSources, message) {
  if (!BROAD_PROJECT_PATTERN.test(String(message || ''))) return [];
  const projectSources = (allSources || []).filter((source) => source.view_kind === 'project');
  return preferDedicatedProjectPages(allSources, projectSources)
    .map((source) => ({
      ...source,
      preferred_component_match: source.presentations?.includes('component') === true,
    }));
}

function dedicatedProjectOverview(allSources, project) {
  const route = project?.entity?.route || project?.route;
  if (!route || route === '/projects') return null;
  return (allSources || []).find((source) => (
    source.source_id !== project.source_id
    && source.route === route
    && !source.anchor
    && source.view_kind === 'prose'
  )) || null;
}

export function preferDedicatedProjectPages(allSources, sources) {
  const normalized = (sources || []).map((source) => {
    if (source?.view_kind !== 'project') return source;
    const detail = dedicatedProjectOverview(allSources, source);
    if (!detail) return source;
    return {
      ...detail,
      entity: {
        ...(detail.entity || {}),
        kind: 'project-detail',
        projectId: source.entity?.id || '',
        companionRichBlock: source.entity?.richBlock || '',
      },
      project_catalog_source_id: source.source_id,
    };
  });
  return mergeSources([], normalized);
}

export function relevantRichSources(message) {
  const tokens = relevanceTokens(message);
  return richSources()
    .filter((source) => directlyMatches(source, tokens))
    .map((source) => ({ ...source, direct_component_match: true }));
}

export function companionRichSources(sources) {
  const companionIds = new Map();
  for (const source of sources || []) {
    const id = source?.entity?.richBlock || source?.entity?.companionRichBlock;
    if (id && !companionIds.has(id)) companionIds.set(id, source.source_id);
  }
  return richSources()
    .filter((source) => companionIds.has(source.source_id))
    .map((source) => ({ ...source, companion_for: companionIds.get(source.source_id) }));
}

function mergeSources(base, extra) {
  const byId = new Map();
  for (const s of base) if (s && s.source_id) byId.set(s.source_id, s);
  for (const s of extra) if (s && s.source_id && !byId.has(s.source_id)) byId.set(s.source_id, s);
  return [...byId.values()];
}

function sourceByIdFromSearch(items, id) {
  if (!id) return null;
  const match = items.find((s) => String(s.source_id || '') === String(id));
  if (match) return match;
  // Fall back to route#anchor key.
  const [route, anchor] = String(id).startsWith('route#')
    ? String(id).slice(6).split('#')
    : [];
  if (route) {
    return items.find((s) => s.route === route && (s.anchor || '') === (anchor || '')) || null;
  }
  return null;
}

export async function candidatesForView({ message, session, latestMessage }) {
  const viewIndex = await viewItems();
  const allSources = (viewIndex.sources || []).map((s) => ({ ...s, title: sourceDisplayTitle(s) }));

  let intent = String(message || '').trim();
  const recent = (session?.turns || []).slice(-3).map((t) => t.text).filter(Boolean).join(' ');
  intent = [recent, latestMessage || message].filter(Boolean).join(' ') || intent;

  let retrieved = [];
  try {
    retrieved = await retrieveAskContexts(intent, 14, allSources);
  } catch {
    retrieved = allSources.slice(0, 24);
  }

  const needed = [];
  if (session) {
    for (const turn of (session.turns || []).slice(-6)) {
      for (const sourceId of turn.source_ids || []) needed.push(sourceId);
    }
  }

  const currentSources = preferDedicatedProjectPages(allSources, needed
    .map((id) => sourceByIdFromSearch(allSources, id))
    .filter(Boolean));

  const currentIntent = latestMessage || message;
  const archiveCandidates = formativeArchiveCandidates(allSources, currentIntent);
  const prioritizedRetrieved = prioritizeFormativeArchive(
    preferDedicatedProjectPages(allSources, mergeSources(retrieved, archiveCandidates)),
    currentIntent,
  );
  const relevantRich = relevantRichSources(currentIntent, prioritizedRetrieved);
  const projectCandidates = broadProjectCandidates(allSources, currentIntent);
  // Broad project requests need the project catalog itself before supporting
  // experience matches. This gives the composer real editorial choice across
  // professional, academic, personal, and formative work.
  const candidatePool = mergeSources(
    projectCandidates,
    mergeSources(prioritizedRetrieved, currentSources),
  );
  const requiredSources = candidatePool.filter((source) => source.required_component_match);
  const candidateSources = mergeSources(candidatePool.slice(0, 15), requiredSources);
  const companions = companionRichSources(candidateSources);
  // A directly relevant original interaction should be visible to the model
  // before secondary prose matches. Activation topics describe when the
  // component itself answers the request, so project names alone do not lift
  // an unrelated demo.
  // Once a project itself is relevant, its registered interaction also enters
  // the catalog as an optional companion. The model can use it when the
  // interaction adds evidence to the story without relying on query-specific
  // hardcoded rules.
  return mergeSources(relevantRich, mergeSources(candidateSources, companions)).slice(0, 20);
}

export async function allViewSources() {
  const data = await viewItems();
  return data.sources || [];
}
