<template>
    <div>
      <h1 data-scroll-reveal>
        Website Traffic
      </h1>
      <article data-scroll-group data-scroll-step="110">
        <p>This page offers a small view of how visitors move through the site, including which pages they open and how activity changes over time. It helps me understand what people find useful and where the site could communicate more clearly.</p>
        <p>Activity appears in aggregate. Individual visitors are not identified.</p>
        <div class='trafficReport' data-scroll-reveal></div>
      </article>
    </div>
  </template>

<script>
import scrollRevealMixin from '../mixins/scrollRevealMixin';

export default {
  name: 'TrafficTab',
  mixins: [scrollRevealMixin],
  data() {
      return {
          scriptModule: null,
      };
  },
  async mounted() {
      // Dynamically import the script when the component is mounted
      this.scriptModule = await import('../assets/js/loadtrafficreport.js');
      if (this.scriptModule && this.scriptModule.initScript) {
          this.scriptModule.initScript();
      }
  },
  unmounted() {
      // Clean up the script when the component is unmounted
      if (this.scriptModule && this.scriptModule.cleanupScript) {
          this.scriptModule.cleanupScript();
      }
      this.scriptModule = null; // Optionally, clear the reference to the module
  },
}
</script>
